 if(tab==='Overview'){const t=scopedTasks().filter(t=>t.status!=='Removed');html=`${admin()?'<div class="toolbar"><button data-new-task>+ Assign task</button></div>'+taskEmployeePicker():''}<div class="kpis">${[['Pending tasks',t.filter(t=>!['Submitted','Closed'].includes(t.status)).length,'pending'],['Completed tasks',t.filter(t=>['Submitted','Closed'].includes(t.status)).length,'completed'],['Assigned tasks',t.filter(t=>taskKind(t)==='assigned').length,'assigned'],['Overdue',t.filter(overdue).length,'overdue']].map(([label,n,view])=>`<button class="card" data-task-view="${view}"><small>${label}</small><strong>${n}</strong><small>Tap to view</small></button>`).join('')}${admin()?`<button class="card" data-task-view="removal"><small>Removal approval requests</small><strong>${t.filter(t=>t.removalRequest?.status==='Requested').length}</strong><small>Tap to review</small></button>`:''}</div>${admin()&&taskView!=='all'?employeeTaskOverview():''}<h2>Report summary · ${esc($('#from').value)} to ${esc($('#to').value)}</h2><div class="grid">${visibleTypes().map(type=>`<button class="summary-card" data-type="${esc(type)}"><small>${type.includes('Production')?'EXISTING SOURCE':type==='Glue Consumption'?'CALCULATED':'REPORT'}</small><h2>${esc(type)}</h2>${summary(type,filtered(),state.batchChangeover).slice(0,3).map(m=>`<div class="metric"><span>${esc(m.label)}</span><b>${esc(m.value)}</b></div>`).join('')}<span class="link">View details & inquiry →</span></button>`).join('')}</div>`;}
